import React from 'react';
import ReactDOM from 'react-dom';
import Field from 'PATH_TO_YOUR_SRC/field'; // e.g. '@alifd/next/src/field'

// Step 1: Prepare an external object to pass into Field
const externalValues = { preExisting: 'keep me' };

class App extends React.Component {
  constructor(props) {
    super(props);
    // Step 2: Initialize Field with the external object
    this.field = new Field(this, { values: externalValues });
  }

  componentDidMount() {
    console.log('Before calling init or setValue:', externalValues);
    // Step 3: Call init to assign an initial value
    const init = this.field.init;
    // this will write into this.field.values['name'] and thus mutate externalValues
    init('name', { initValue: 'first' });
    console.log('After init:', externalValues);

    // Step 4: Call setValue to update the field's value
    this.field.setValue('name', 'second');
    console.log('After setValue:', externalValues);
  }

  render() {
    // To satisfy React, render an input bound to the same field
    return <input {...this.field.init('name')} placeholder="Check console" />;
  }
}

// Render the demo
ReactDOM.render(<App />, document.getElementById('root'));
